# spire-server-config.yaml (云端)
apiVersion: v1
kind: ConfigMap
metadata:
  name: spire-server
  namespace: spire
data:
  server.conf: |
    server {
      bind_address = "0.0.0.0"
      bind_port = "8081"
      socket_path = "/tmp/spire-server/private/api.sock"
      trust_domain = "edge.example.com"
      data_dir = "/run/spire/data"
      log_level = "DEBUG"

      # 证书有效期（边缘场景建议较短）
      default_svid_ttl = "1h"

      # CA 配置
      ca_subject = {
        country = ["CN"]
        organization = ["Edge Corp"]
        common_name = "Edge SPIRE CA"
      }
      ca_ttl = "24h"
    }

    plugins {
      # 数据存储
      DataStore "sql" {
        plugin_data {
          database_type = "postgres"
          connection_string = "host=postgres port=5432 dbname=spire..."
        }
      }

      # 节点证明 (Kubernetes 方式)
      NodeAttestor "k8s_psat" {
        plugin_data {
          clusters = {
            "edge-cluster" = {
              service_account_allow_list = ["spire:spire-agent"]
            }
          }
        }
      }

      # 密钥管理
      KeyManager "disk" {
        plugin_data {
          keys_path = "/run/spire/data/keys.json"
        }
      }

      # 健康检查
      UpstreamAuthority "disk" {
        plugin_data {
          cert_file_path = "/run/spire/config/dummy_root_ca.crt"
          key_file_path = "/run/spire/config/dummy_root_ca.key"
        }
      }
    }

    health_checks {
      listener_enabled = true
      bind_address = "0.0.0.0"
      bind_port = "8080"
      live_path = "/live"
      ready_path = "/ready"
    }

---
# spire-agent-config.yaml (边缘端)
apiVersion: v1
kind: ConfigMap
metadata:
  name: spire-agent
  namespace: spire
data:
  agent.conf: |
    agent {
      data_dir = "/run/spire"
      log_level = "DEBUG"
      server_address = "spire-server.cloud.example.com"
      server_port = "8081"
      socket_path = "/run/spire/sockets/agent.sock"
      trust_bundle_path = "/run/spire/bundle/bundle.crt"
      trust_domain = "edge.example.com"
    }

    plugins {
      NodeAttestor "k8s_psat" {
        plugin_data {
          cluster = "edge-cluster"
        }
      }

      # 工作负载证明
      WorkloadAttestor "k8s" {
        plugin_data {
          skip_kubelet_verification = true
          node_name_env = "NODE_NAME"
        }
      }

      KeyManager "memory" {
        plugin_data {}
      }
    }

---
